/** Pure diff computation loaded only by the owned module Worker. @module */
import { computeHunkDiffs } from './diff.ts'
import type { FileDiff } from '@deepseek-ai/dsh-tools'

/** Bounded, detached text supplied after the filesystem reports a successful mutation. */
export interface DiffInput { path: string; before: string | null; after: string }

/** Produce the same contextual hunks as the original file tool.
 * @param input - plain JSON text and display path; no filesystem capabilities.
 * @returns contextual hunks, or a create/full-replacement preview when no basis exists.
 */
export function execute(input: DiffInput): { diffs: FileDiff[] } {
  return { diffs: input.before === null
    ? [{ path: input.path, oldText: null, newText: input.after }]
    : computeHunkDiffs(input.path, input.before, input.after) }
}
